--
-- When these tables are queried:
-- Q1:
--   SELECT T1.NCESSchool FROM schools AS T1
--   INNER JOIN frpm AS T2 ON T1.CDSCode = T2.CDSCode
--   ORDER BY T2.`ENROLLMENT (AGES 5-17)` DESC LIMIT 5
-- will return only the NCESSchool column (e.g. School_D, School_F, School_C, School_E, School_B),
-- while
-- Q2:
--   SELECT NCESSchool, `School Name`, `ENROLLMENT (AGES 5-17)` FROM frpm
--   INNER JOIN schools ON frpm.CDSCode = schools.CDSCode
--   ORDER BY `ENROLLMENT (AGES 5-17)` DESC LIMIT 5
-- will return three columns. Since the SCHOOLS table has no column named "School Name", that column will be NULL
-- (or cause an error) depending on the SQL dialect. In either case the result sets differ in structure and content.

INSERT INTO SCHOOLS (CDSCODE, STATUSTYPE, COUNTY, DISTRICT, DOC, DOCTYPE, LASTUPDATE) VALUES ('X1', 'Active', 'CountyA', 'DistrictX', 'doc1', 'type', '2023-01-01');
INSERT INTO SCHOOLS (CDSCODE, STATUSTYPE, COUNTY, DISTRICT, DOC, DOCTYPE, LASTUPDATE) VALUES ('X2', 'Active', 'CountyA', 'DistrictX', 'doc2', 'type', '2023-01-01');
