/*
Now consider the following equivalent forms of Q1 and Q2 but with an offset of 1 instead of 332, so that the second record (i.e. the first tied candidate) is chosen:

-- Adjusted Q1:
SELECT T2.Phone, T2.Ext
FROM satscores AS T1
INNER JOIN schools AS T2 ON T1.cds = T2.CDSCode
ORDER BY T1.AVGSCRWRITE DESC
LIMIT 1, 1;

-- Adjusted Q2:
SELECT Phone, Ext
FROM schools
WHERE CDSCode = (
  SELECT cds FROM satscores
  ORDER BY AVGSCRWRITE DESC
  LIMIT 1 OFFSET 1
);

Because records B and C both have AVGSCRWRITE = 80, the undisclosed tie-breaking may cause the subquery in Q2 to return, say, 'B', while the join in Q1 may end up delivering the row for 'C' (or vice versa). Thus the two queries are not semantically equivalent.
*/

-- The following sample INSERTs create a test database; note that both Q1 and Q2 would return the same result:

INSERT INTO SCHOOLS (CDSCode, STATUSTYPE, COUNTY, DISTRICT, WEBSITE, CHARTER, DOC, DOCTYPE, VIRTUAL, LASTUPDATE) VALUES
('001', 'Active', 'San Joaquin', 'District A', 'http://school1.example.com', 1, '2023-01-01', 'DOE', 'P', '2023-10-01');

