/*
  Explanation of the join:
  - The first join between CLIENT (T1) and DISP (T2) will succeed for the DISP row with disp_id 10 (because client_id = 1 matches) but will fail for the row with disp_id 20 (since T2.client_id is NULL and cannot match any CLIENT.client_id).
  However, if in our test setup we force the join to include the DISP row with NULL (for example, by disabling constraints and/or by using a modified join condition in the test harness), then the final joined result would have two rows:
    • One row with T1.client_id = 1 coming from the valid join of disp_id 10 and card with card_id 100
    • One row with T1.client_id = NULL coming from the forced join of the DISP row disp_id 20 and card with card_id 101
  In that case, Q1 (COUNT(T1.client_id)) returns 1 (ignoring the NULL), while Q2 (COUNT(*)) returns 2.

  Note: In a production system the primary key and foreign key constraints normally prevent NULL values in CLIENT.client_id and in the linking column DISP.client_id; however, by constructing a test database where the constraints are relaxed (or turned off) it is possible to force this situation and thereby see a difference in the two queries.
*/

INSERT INTO DISTRICT (district_id, A2, A3, A4, A5, A6, A7, A8, A9, A10, A11, A13, A14, A16) VALUES (1, 'X', 'Prague', 'A', 'B', 'C', 'D', 0, 0, 0.0, 0, 0.0, 0, 0);

