counterexample:
INSERT INTO MOLECULE VALUES ('mol1');

-- Insert two atoms representing a connection, and two different atoms for the same bond (e.g. different ways to represent the same bond in a redundant recording)
INSERT INTO ATOM VALUES ('a1', 'mol1');
INSERT INTO ATOM VALUES ('a2', 'mol1');
INSERT INTO ATOM VALUES ('a3', 'mol1');
INSERT INTO ATOM VALUES ('a4', 'mol1');

-- Insert a bond with bond_type '#' that belongs to mol1
INSERT INTO BOND VALUES ('b1', 'mol1', '#');

-- Insert two CONNECTED rows for the same bond 'b1' (they have different atom order even though they represent the same bond in the molecule)
INSERT INTO CONNECTED VALUES ('a1', 'a2', 'b1');
INSERT INTO CONNECTED VALUES ('a3', 'a4', 'b1');

-- Optionally, insert a bond with a different type and a CONNECTED row so that rows for b1 are the only ones that qualify for '#'
INSERT INTO BOND VALUES ('b2', 'mol1', '*');
INSERT INTO CONNECTED VALUES ('a1', 'a3', 'b2');

-- Q1 will join from the BOND table: it will consider only b1 (because b2's bond_type is not '#') and then join to CONNECTED producing the two rows from b1.
-- Q2 will start from CONNECTED: it will join all CONNECTED rows and then select only those whose matching bond has bond_type '#' (thus producing two rows for b1); however, if the application logic intended a one-to-one correspondence for each BOND then having two separate CONNECTED rows for the same bond b1 (i.e. duplicate representations) makes the query Q2 semantically different from Q1.

