counterexample:
-- For the sake of this counterexample we assume that the DBMS allows deferring or disabling of the foreign key check so that the anomaly can be inserted without violating constraints.

-- Insert a molecule
INSERT INTO MOLECULE (MOLECULE_ID) VALUES ('M1');

-- Insert a BOND row that is erroneously used by the mis‐linked row
INSERT INTO BOND (BOND_ID, MOLECULE_ID, BOND_TYPE) VALUES ('BOND_X', 'M1', 'double');

-- Insert atoms
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID) VALUES ('A1', 'M1');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID) VALUES ('A2', 'M1');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID) VALUES ('B1', 'M1');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID) VALUES ('B2', 'M1');

-- Insert a CONNECTED row that is mis‐linked: its bond_id is 'TR001_6_9' even though it joins (erroneously) to the BOND row with bond_id 'BOND_X'
INSERT INTO CONNECTED (ATOM_ID, ATOM_ID2, BOND_ID) VALUES ('A1', 'A2', 'TR001_6_9');

-- Insert the proper BOND row for bond_id 'TR001_6_9' and a correctly linked CONNECTED row
INSERT INTO BOND (BOND_ID, MOLECULE_ID, BOND_TYPE) VALUES ('TR001_6_9', 'M1', 'single');
INSERT INTO CONNECTED (ATOM_ID, ATOM_ID2, BOND_ID) VALUES ('B1', 'B2', 'TR001_6_9');

/*
   Now, when running the queries:

   Q1: SELECT T1.bond_type, T2.atom_id, T2.atom_id2
       FROM BOND AS T1 INNER JOIN CONNECTED AS T2
         ON T1.bond_id = T2.bond_id
       WHERE T2.bond_id = 'TR001_6_9';

       Q1 will return both rows because it checks only that the CONNECTED row holds 'TR001_6_9' in its bond_id. In our mis‐linked row, even though T1 (joined via the (mis-)link) comes from BOND.BOND_ID = 'BOND_X', the WHERE clause passes because T2.bond_id = 'TR001_6_9'.

   Q2: SELECT T1.bond_type, T2.atom_id, T2.atom_id2
         FROM BOND AS T1 INNER JOIN CONNECTED AS T2
         ON T1.bond_id = T2.bond_id
         WHERE T1.bond_id = 'TR001_6_9';

       Q2 will return only the correctly linked row since it requires that the BOND row’s bond_id equals 'TR001_6_9'.
*/

