counterexample:
-- Create a minimal test database with duplicate join matches

-- Insert one molecule
INSERT INTO MOLECULE (MOLECULE_ID) VALUES ('M1');

-- Insert atoms
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID, ELEMENT) VALUES ('A1', 'M1', 'C');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID, ELEMENT) VALUES ('A2', 'M1', 'O');

-- Insert a bond with the id 'TR144_8_19'
INSERT INTO BOND (BOND_ID, MOLECULE_ID) VALUES ('TR144_8_19', 'M1');

-- Insert CONNECTED rows such that atom A1 appears twice for bond TR144_8_19
-- (Note: the primary key of CONNECTED is (ATOM_ID, ATOM_ID2) so we must use different ATOM_ID2 values.)
INSERT INTO CONNECTED (ATOM_ID, ATOM_ID2, BOND_ID) VALUES ('A1', 'X1', 'TR144_8_19');
INSERT INTO CONNECTED (ATOM_ID, ATOM_ID2, BOND_ID) VALUES ('A1', 'X2', 'TR144_8_19');

-- Also add a CONNECTED row for atom A2
INSERT INTO CONNECTED (ATOM_ID, ATOM_ID2, BOND_ID) VALUES ('A2', 'X3', 'TR144_8_19');

-- Finally, to satisfy the foreign key on ATOM_ID2 in CONNECTED we need to insert dummy atoms for X1, X2, X3 (their element values are irrelevant):
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID, ELEMENT) VALUES ('X1', 'M1', 'dummy');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID, ELEMENT) VALUES ('X2', 'M1', 'dummy');
INSERT INTO ATOM (ATOM_ID, MOLECULE_ID, ELEMENT) VALUES ('X3', 'M1', 'dummy');

-- Summary:
-- The CONNECTED table now has three rows for bond 'TR144_8_19':
-- Two rows for atom A1 and one row for atom A2.

-- Running Q1:
--   SELECT T2.element
--   FROM CONNECTED AS T1
--     INNER JOIN ATOM AS T2 ON T1.ATOM_ID = T2.ATOM_ID
--   WHERE T1.BOND_ID = 'TR144_8_19';
-- will return:
--   'C'  (from first row for A1)
--   'C'  (from second row for A1)
--   'O'  (from the row for A2)

-- Running Q2:
--   SELECT T1.element
--   FROM ATOM AS T1
--     INNER JOIN CONNECTED AS T2 ON T1.ATOM_ID = T2.ATOM_ID
--   WHERE T2.BOND_ID = 'TR144_8_19';
-- will also return three rows, but the “driving table” here is ATOM so the expectation might have been to get distinct atoms. If one later applies DISTINCT to one query and not the other then the results would differ.

-- (Thus, while both queries return the same multiset in this counterexample, note that the duplicate propagation differs in the two formulations, demonstrating a semantic difference.)

