-- Assume the following user–defined function exists in the SQL dialect used:
-- CREATE FUNCTION BAD_COMPARE(val VARCHAR, expected VARCHAR) RETURNS BOOLEAN AS $$
--    IF val = expected THEN RETURN TRUE;
--    ELSE RAISE EXCEPTION 'Value % is not equal to %', val, expected;
--    END IF;
-- $$ LANGUAGE plpgsql;

-- Here is the test data. We insert one row into SETS that will cause BAD_COMPARE(T1.block, 'Ravnica')
-- to fail if evaluated. (The code below uses the plain column value 'ERROR' so that the wrapped function would error.)

