/* Insert two posts with ViewCount = 1910 */
INSERT INTO POSTS (ID, VIEWCOUNT, OWNERUSERID, LASTEDITORUSERID, PARENTID) VALUES (1, 1910, 1, 1, NULL);
INSERT INTO POSTS (ID, VIEWCOUNT, OWNERUSERID, LASTEDITORUSERID, PARENTID) VALUES (2, 1910, 1, 1, NULL);

/* Insert one comment only for post with ID = 1 */
INSERT INTO COMMENTS (ID, POSTID, USERID) VALUES (1, 1, 1);

/*
Now consider these two alternative queries which use a LEFT JOIN rather than an INNER JOIN.

Query A (counting posts.Id):
  SELECT COUNT(T1.Id)
  FROM POSTS AS T1 LEFT JOIN COMMENTS AS T2 ON T1.Id = T2.PostId
  WHERE T1.ViewCount = 1910;

Query B (counting comments.Id):
  SELECT COUNT(T2.Id)
  FROM POSTS AS T1 LEFT JOIN COMMENTS AS T2 ON T1.Id = T2.PostId
  WHERE T1.ViewCount = 1910;

For the test data above, Query A returns 2 (both posts are counted) while Query B returns 1 (only the post with a matching comment contributes a non-null T2.Id).

This illustrates that even though an inner join would make Q1 and Q2 return the same result, the two formulations are not semantically equivalent if one intends to count posts versus comments when missing matches are possible.
*/

INSERT INTO USERS (ID) VALUES (3025);

INSERT INTO POSTS (ID, OWNERUSERID, FAVORITECOUNT, LASTEDITORUSERID, PARENTID) 
VALUES (1, 3025, 10, 3025, NULL);

INSERT INTO COMMENTS (ID, POSTID, CREATIONDATE, USERID) 
VALUES (1, 1, '2014-04-23 20:29:39', 3025);

