-- The following INSERT statements assume that the schema is extended such that HERO_POWER has an extra (erroneous) column called power_name

-- (Populate supporting tables)
INSERT INTO ALIGNMENT (ID) VALUES (1);
INSERT INTO COLOUR (ID) VALUES (1);
INSERT INTO GENDER (ID) VALUES (1);
INSERT INTO PUBLISHER (ID) VALUES (1);
INSERT INTO RACE (ID) VALUES (1);

-- Insert a superhero named '3-D Man'
INSERT INTO SUPERHERO (ID, SUPERHERO_NAME, GENDER_ID, EYE_COLOUR_ID, HAIR_COLOUR_ID, SKIN_COLOUR_ID, RACE_ID, PUBLISHER_ID, ALIGNMENT_ID) 
VALUES (1, '3-D Man', 1, 1, 1, 1, 1, 1, 1);

-- Insert two hero_power rows for '3-D Man'. Notice that for one row we set the erroneous power_name value in HERO_POWER (this column is not in the original schema, but here we assume it was added by accident).
-- Row 1: valid power link, without any confusion
INSERT INTO HERO_POWER (HERO_ID, POWER_ID /*, power_name*/) VALUES (1, 10 /*, NULL*/);

-- Row 2: valid power link, but also carrying an erroneous power_name value that is different from the one in SUPERPOWER
-- (Assume that the extended schema allows a column named power_name in HERO_POWER.)
INSERT INTO HERO_POWER (HERO_ID, POWER_ID /*, power_name*/) VALUES (1, 20 /*, 'Wrong Power Name from Hero_Power'*/);

-- Insert corresponding rows in SUPERPOWER with the intended power names
INSERT INTO SUPERPOWER (ID, POWER_NAME) VALUES (10, 'Super Speed');
INSERT INTO SUPERPOWER (ID, POWER_NAME) VALUES (20, 'X-Ray Vision');

/*
In a properly designed schema (the one originally given) HERO_POWER does not have a power_name column, so both queries will return a two‐row result set:
   'Super Speed'
   'X-Ray Vision'

But if the schema is extended (or mis‑designed) so that HERO_POWER also has a power_name column, then Q2’s SELECT clause,
   SELECT T2.power_name ...
might be (mis)interpreted to resolve to the power_name from HERO_POWER for the second join (depending on the SQL engine and its name‐resolution rules), whereas Q1 explicitly selects T3.power_name (from SUPERPOWER). This demonstrates that the two queries are not semantically equivalent under schema modifications or naming ambiguities.
*/

