-- First, insert duplicate publisher records for 'DC Comics'
INSERT INTO publisher (id, publisher_name) VALUES (1, 'DC Comics');
INSERT INTO publisher (id, publisher_name) VALUES (2, 'DC Comics');

-- Insert supporting rows for required referenced tables (using dummy IDs);
-- These inserts create one row per table so that the foreign key constraints in SUPERHERO are satisfied.
INSERT INTO gender (id) VALUES (1);
INSERT INTO colour (id) VALUES (1);
INSERT INTO race (id) VALUES (1);
INSERT INTO alignment (id) VALUES (1);

-- Now, suppose that due to a data‐quality problem the same superhero is recorded twice (with different primary keys) even though they represent the same character.
-- The first row links the hero to the first publisher record and the second row links the hero to the second publisher record.
-- Q1, which counts all rows, will return 2. Q2, if one were to treat these two rows as a duplicate (i.e. after deduplication on the logical superhero), would ideally return 1.
-- (Note: Since the schema forces different IDs, this counterexample relies on the idea that two rows (with id 100 and 101) actually represent the same superhero.
-- In real life the duplicate join might occur via a one‐to‐many join rather than duplicate master records.)

INSERT INTO superhero (id, publisher_id, gender_id, eye_colour_id, hair_colour_id, skin_colour_id, race_id, alignment_id)
  VALUES (100, 1, 1, 1, 1, 1, 1, 1);
INSERT INTO superhero (id, publisher_id, gender_id, eye_colour_id, hair_colour_id, skin_colour_id, race_id, alignment_id)
  VALUES (101, 2, 1, 1, 1, 1, 1, 1);

-- Under these circumstances:
-- Q1:
--   SELECT COUNT(T1.id) ...
-- returns 2 (since there are two rows joining with a 'DC Comics' publisher).
-- Q2:
--   SELECT COUNT(DISTINCT T1.id) ...
-- returns 2 as well if we look only at the raw values because the two rows have different primary keys.

-- However, if one interprets these two rows as duplicate representations of the same superhero (i.e. the deduplication should be done on a logical identity rather than the surrogate primary key), then Q2’s use of DISTINCT prevents overcounting.

-- Thus, this counterexample shows that a join that multiplies rows (because of duplicate publisher records or duplicate entries for the same hero) can cause Q1 and Q2 to yield different counts.

-- (In practice, one should eliminate such data anomalies so that the join does not create spurious duplicates.)

