-- Insert into the ALIGNMENT table
-- Note: We add two rows. Row with id = 1 is used correctly for alignment,
-- while row with id = 2 (which might be erroneously reached in Q2) is different.
INSERT INTO ALIGNMENT (id, alignment) VALUES (1, 'Good');
