VALUES (1, 1, 1, 1, 1, 1, 38, 1);

/*
Now assume:
Q1: SELECT T2.publisher_name FROM superhero AS T1
       INNER JOIN publisher AS T2 ON T1.publisher_id = T2.id
       WHERE T1.id = 38;
--> This returns no rows because there is no superhero with id 38.

Q2 (with the intended fix): SELECT T2.publisher_name FROM superhero AS T1
       INNER JOIN publisher AS T2 ON T1.publisher_id = T2.id
       WHERE T1.publisher_id = 38;
--> This returns 'Marvel' because the superhero with id 1 has publisher_id = 38 and joins with publisher 38.

This counterexample shows that if Q2 uses T1.publisher_id = 38 (instead of T1.id = 38), the two queries will yield different results.
*/

