-- First, insert into circuits in a way that (illegally) creates duplicate rows for the same circuitId
INSERT INTO circuits (circuitId, circuitRef, name, location, url) VALUES (1, 'c1', 'Circ Duplicate A', 'Shanghai', 'http://example.com/A');
INSERT INTO circuits (circuitId, circuitRef, name, location, url) VALUES (1, 'c1', 'Circ Duplicate B', 'Shanghai', 'http://example.com/B');

