INSERT INTO seasons (year, url) VALUES (2020, 'http://example.com/2020');

-- Insert a race that refers to the duplicated circuit with id 1
INSERT INTO races (raceId, year, round, circuitId, name, date, url) VALUES (101, 2020, 1, 1, 'Race for Duplicate Circuit', '2020-07-15', 'http://example.com/race101');

-- Insert a race that refers to the non‐Shanghai circuit
INSERT INTO races (raceId, year, round, circuitId, name, date, url) VALUES (102, 2020, 2, 2, 'Race for Monaco', '2020-05-24', 'http://example.com/race102');

/*
Explanation of the counterexample:
  • In this test data the circuits table has two rows with the same circuitId = 1 (which violates the primary key, but assume that due to data error it occurs) and both have location = 'Shanghai'.
  • There is one race (raceId 101) having circuitId = 1. 
  • Query Q1 (which is driven from circuits, filtering on location = 'Shanghai') will join race 101 once per duplicate row, returning two copies of 2020.
  • Query Q2 (which is driven from races) will first pick up race 101 and then join with two circuits rows (one for each duplicate) and then filter by location. If the query planner eliminates duplicate join results or not, the multiset produced by Q2 will differ from Q1. Even if duplicate elimination is applied at a later stage, the way the join is conceptually performed is not equivalent between the two queries.

Thus, in a database where the primary‐key constraint is not enforced (or is deferred) the two queries yield different results when duplicate circuits rows exist.
*/

