-- Insert results. To illustrate a non‐uniform duplication effect imagine that for raceId=1 one result row appears only once and another result row appears twice because of data anomaly in results as well.
-- Here we insert two result rows with different fastestLapSpeed values. 
INSERT INTO RESULTS (resultId, raceId, driverId, constructorId, grid, positionText, positionOrder, points, laps, fastestLapSpeed, statusId) 
  VALUES (1, 1, 1, 1, 1, '1', 1, 10, 50, '200', 1);

INSERT INTO RESULTS (resultId, raceId, driverId, constructorId, grid, positionText, positionOrder, points, laps, fastestLapSpeed, statusId) 
  VALUES (2, 1, 1, 1, 2, '2', 2, 8, 50, '100', 1);

-- Now suppose that due to another data anomaly the second result row (with 100) gets duplicated in the source (or appears twice in a join) while the first result row appears only once. In Q1 the join will return three rows (one 200 and two 100’s) resulting in AVG = (200 + 100 + 100) / 3 = 133.33, 
-- whereas Q2 – which uses an IN subquery and does not multiply rows based on duplicates in races – will compute the average as if there were only two rows: (200 + 100) / 2 = 150.

-- To simulate that, we insert an extra result row with the same values as the second row (though note that in a proper database this would violate the primary key on resultId; here we assume that the data anomaly occurs in the join due to duplicates in the races table rather than in results).

INSERT INTO RESULTS (resultId, raceId, driverId, constructorId, grid, positionText, positionOrder, points, laps, fastestLapSpeed, statusId) 
  VALUES (3, 1, 1, 1, 2, '2', 2, 8, 50, '100', 1);

-- Under this contrived test data environment, Q1 and Q2 will yield different averages because Q1’s join inadvertently “multiplies" the 100 value while Q2’s IN filtering does not.

