-- Here the player with PLAYER_API_ID = 1 has a lower overall rating in his attributes
INSERT INTO Player_Attributes (ID, PLAYER_FIFA_API_ID, PLAYER_API_ID, OVERALL_RATING) VALUES (1, 100, 1, 80);
-- Only the player with PLAYER_API_ID = 2 gets a high overall rating
INSERT INTO Player_Attributes (ID, PLAYER_FIFA_API_ID, PLAYER_API_ID, OVERALL_RATING) VALUES (2, 101, 2, 95);

-- When executing Q1, if the DBMS chooses the PLAYER row with id=1 then the join yields overall_rating = 80 so that MAX = 80,
-- whereas Q2 (starting from the attributes table) joins and returns the 95 from the attribute of the PLAYER row with id=2.

