-- For the counterexample, assume that Q1 is actually written as follows:
-- Q1: SELECT COUNT(T1.member_id) FROM MEMBER AS T1
--      LEFT JOIN MAJOR AS T2 ON T1.LINK_TO_MAJOR = T2.MAJOR_ID AND T2.MAJOR_NAME = 'Environmental Engineering';

-- And Q2 as originally written (using an INNER JOIN & WHERE condition):
-- Q2: SELECT COUNT(T1.member_id) FROM MEMBER AS T1
--      INNER JOIN MAJOR AS T2 ON T1.LINK_TO_MAJOR = T2.MAJOR_ID
--      WHERE T2.MAJOR_NAME = 'Environmental Engineering';

-- Then Q1 returns 2 (since both members are present, with the second having a NULL from T2),
-- while Q2 returns 1 (only the member linked to the 'Environmental Engineering' major is joined).

