INSERT INTO EXPENSE VALUES ('EX1','Parking', 10, 'M1', 'B1');
INSERT INTO EXPENSE VALUES ('EX2','Parking', 20, 'M1', 'B1');

-- Now create an outer query context that (illegally) provides a column named cost.
-- For the purpose of this counterexample we simulate the outer context by creating a temporary table that
-- has a column named cost, and then selecting from it while embedding the two inner queries.

-- (Assume that the SQL system allows the following temporary table creation and that its column name
-- interferes with the unqualified reference in Q1.)

CREATE TEMPORARY TABLE dummy (cost INTEGER);

INSERT INTO dummy VALUES (100);

-- Here the outer query selects the value of the outer column dummy.cost along with the results of our two subqueries:

-- Q1 is: SELECT SUM(cost) FROM expense WHERE expense_description = 'Parking'
-- Q2 is: SELECT SUM(T1.cost) FROM expense AS T1 WHERE T1.expense_description = 'Parking'

-- In a SQL system with the problematic name resolution, Q1 will pick up dummy.cost (i.e. 100) instead of summing 10 and 20,
-- while Q2 returns 30.

-- Example outer query to test the difference:

SELECT 
  dummy.cost AS outer_cost,
  (SELECT SUM(cost) FROM EXPENSE WHERE expense_description = 'Parking') AS q1,
  (SELECT SUM(T1.cost) FROM EXPENSE AS T1 WHERE T1.expense_description = 'Parking') AS q2
FROM dummy;

-- Expected (nonstandard) result in the buggy system:
-- outer_cost = 100, q1 = 100, q2 = 30

-- In a fully standard SQL system both q1 and q2 would be 30, showing that the problem arises only in environments where
-- unqualified names in subqueries are erroneously resolved to outer columns.

