/* First, alter the gasstations table by adding a new column named TransactionID. This step does not violate the primary‐key constraint on GasStationID. */
ALTER TABLE gasstations
  ADD COLUMN TransactionID INT;

/* Now insert a gas station row. Note that we leave the new TransactionID as NULL. */
INSERT INTO gasstations (GasStationID, Country, TransactionID) VALUES (1, 'CZE', NULL);

/* Insert a transaction row. Its TransactionID is not null and Price>1000 and it joins with GASSTATIONS by GasStationID. */
INSERT INTO transactions_1k (TransactionID, GasStationID, Price) VALUES (100, 1, 1500);

/* When executing Q1:
   SELECT COUNT(T1.TransactionID) ...
 it will look at the transaction row value 100 and count it (result = 1).

   But when executing Q2:
   SELECT COUNT(TransactionID) ...
 the unqualified column name TransactionID will resolve (in our test DB) to the one from gasstations, which is NULL, meaning that row is not counted (result = 0).
 This demonstrates that Q1 and Q2 return different results. */

